import math

def count_divisors(n):
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def d(n):
    # d(n) is the number of positive divisors of n other than 1 and itself.
    if n <= 1:
        return 0 # 1 has only 1 divisor, so 0 divisors excluding 1 and itself. 0 has no positive divisors.
    tau_n = count_divisors(n)
    return tau_n - 2

# Brute force search
max_n = 10000
min_a_found = float('inf')
results = []

for n in range(1, max_n + 1):
    d_n = d(n)
    d_n_plus_735 = d(n + 735)

    if d_n == d_n_plus_735:
        a = d_n
        results.append((n, n + 735, a))
        if a < min_a_found:
            min_a_found = a

print(f"Found {len(results)} pairs where d(n) = d(n+735) up to n={max_n}.")
print(f"Minimum 'a' found in this range: {min_a_found}")
# Print a few examples to record
print("First 5 results (n, n+735, a):")
for i in range(min(5, len(results))):
    print(results[i])

def d(n):
    """Calculates the number of positive divisors of n other than 1 and itself (d(n) = tau(n) - 2)."""
    if n <= 0:
        return -1
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i != 1 and i != n:
                count += 1
            if n // i != i and n // i != 1 and n // i != n:
                count += 1
    return count

